-- ============================================================================
-- V008: Daily report cycle (Reasoning Layer)
-- ============================================================================
-- Persists the 3-stage daily reports (pre-open / mid-session / pre-close)
-- generated by the DailyReportEngine. Each report is stored as strict JSON
-- plus a concise readable summary for quick review.

CREATE TABLE IF NOT EXISTS daily_reports (
    report_id       INTEGER PRIMARY KEY AUTOINCREMENT,
    report_type     TEXT    NOT NULL CHECK(report_type IN ('pre_open','mid_session','pre_close')),
    report_date     TEXT    NOT NULL,
    report_json     TEXT    NOT NULL,
    summary         TEXT,
    created_at      TEXT    NOT NULL DEFAULT (datetime('now'))
);

CREATE INDEX IF NOT EXISTS idx_daily_reports_type_date
    ON daily_reports(report_type, report_date);
